function makeShelf() {
  return {
    items: [],

    add(course) {
      this.items.push(course);
      return this;
    },

    names() {
      return this.items.map((c) => c.name).join(' / ');
    },

    totalHours() {
      let total = 0;
      this.items.forEach((c) => {
        total += c.hours;
      });
      return total;
    },
  };
}

// 이 함수는 그대로 두세요
function report(courses) {
  const shelf = makeShelf();
  courses.forEach((c) => shelf.add(c));
  return shelf.names() + ' / 합계 ' + shelf.totalHours() + '시간';
}
